-- ═══════════════════════════════════════════════════════════════
-- Fluenci seed: Chinese (zh) B2 "Complex Grammar" unit rebuild
-- + grammar_rules reference set for zh (A1-B2).
--
-- STAGED SEED — review before applying. Replaces the incorrect
-- European-template lessons (Subjunctive Mood, Complex Tenses, …)
-- with real upper-intermediate Mandarin grammar (HSK 4-5):
-- 把-construction, 被-passives, verb complements, aspect 了/着/过,
-- comparisons, plus a mixed Review & Test lesson.
--
-- All distractors, error sentences and tile permutations were
-- machine-checked against lib/grading.ts fuzzy matching (edit
-- distance <=1 for answers <=4 chars, <=2 otherwise) so no wrong
-- answer is accidentally accepted.
--
-- Apply via Supabase MCP/dashboard. Never db reset / db push.
-- ═══════════════════════════════════════════════════════════════

BEGIN;

UPDATE units SET
  title = 'Complex Grammar',
  description = '把 and 被 sentences, verb complements, aspect particles 了/着/过, and comparisons (HSK 4-5)'
WHERE id = 'aabbccdd-8888-4006-0000-b20000000000';

-- ─── The 把 Construction ───
UPDATE lessons SET title = 'The 把 Construction', description = 'Move the object before the verb with 把 to say what was done to it' WHERE id = 'aabbccdd-8888-4006-0001-b20000000000';
DELETE FROM exercises WHERE lesson_id = 'aabbccdd-8888-4006-0001-b20000000000';

-- ─── Passives with 被 ───
UPDATE lessons SET title = 'Passives with 被', description = 'Express what happened to things with 被, 让/叫, and the bare (unmarked) passive' WHERE id = 'aabbccdd-8888-4006-0002-b20000000000';
DELETE FROM exercises WHERE lesson_id = 'aabbccdd-8888-4006-0002-b20000000000';

-- ─── Verb Complements ───
UPDATE lessons SET title = 'Verb Complements', description = 'Results (听懂, 找到), directions (拿出来), and possibility (吃不完)' WHERE id = 'aabbccdd-8888-4006-0003-b20000000000';
DELETE FROM exercises WHERE lesson_id = 'aabbccdd-8888-4006-0003-b20000000000';

-- ─── Aspect: 了, 着, 过 ───
UPDATE lessons SET title = 'Aspect: 了, 着, 过', description = 'Completed actions, ongoing states, and past experiences' WHERE id = 'aabbccdd-8888-4006-0004-b20000000000';
DELETE FROM exercises WHERE lesson_id = 'aabbccdd-8888-4006-0004-b20000000000';

-- ─── Comparisons ───
UPDATE lessons SET title = 'Comparisons', description = '比, 没有, 不如 and 越来越' WHERE id = 'aabbccdd-8888-4006-0005-b20000000000';
DELETE FROM exercises WHERE lesson_id = 'aabbccdd-8888-4006-0005-b20000000000';

-- ─── Review & Test ───
UPDATE lessons SET title = 'Review & Test', description = 'Mixed practice: 把, 被, complements, aspect and comparisons' WHERE id = 'aabbccdd-8888-4006-0006-b20000000000';
DELETE FROM exercises WHERE lesson_id = 'aabbccdd-8888-4006-0006-b20000000000';

-- ─── Grammar rules reference set (zh, A1-B2) ───
ON CONFLICT (language, rule_name) DO UPDATE SET
  cefr_level = EXCLUDED.cefr_level,
  title = EXCLUDED.title,
  explanation = EXCLUDED.explanation,
  examples = EXCLUDED.examples,
  common_errors = EXCLUDED.common_errors,
  tags = EXCLUDED.tags;

COMMIT;
